src/execute/execute_fact_stmt/well_defin.source:
//! Binder-object WD: FnSet / AnonymousFn / SetBuilder.
//!
//! Definition-side: open a proof-scope local env, WD param carriers, WD
//! dom/facts under binders, WD ret_set / body. Success carries `local_env`.
//! Example: `fn(x R: x > 0) R` needs `R` WD, binder `x`, WD of `x > 0`, WD of ret `R`.

use super::entry::{ObjWellDefinedProof, VerifyObjWellDefinedResult};
use super::fail_to_verify_obj_well_defined::*;
use super::helper::set_bound_parameters_to_typed_parameter_list;
use super::obj_well_defined_proof_by_def::*;
use crate::ast::fact::{AtomicFact, InFact, QuantifierFreeFact};
use crate::ast::obj::{AnonymousFn, FnSet, FunctionSpace, Obj, SetBuilder, SetFormer};
use crate::ast::param::{ParamType, TypedParameterGroup, TypedParameterList};
use crate::execute::execute_fact_stmt::verify_fact_result::VerifyFactResult;
use crate::execute::execute_fact_stmt::well_defined_results::well_defined_result::{
    FactWellDefinedProof, FailToVerifyFactWellDefinedResult, VerifyFactWellDefinedResult,
};
use crate::execute::execute_fact_stmt::VerifyState;
use crate::instantiate::quantifier_free_fact_to_fact;
use crate::runtime::{Runtime, RuntimeResult};

impl Runtime {
    // `fn(x R: x > 0) R` — param types → binders → dom WD → ret_set WD; keep local_env.
    pub(super) fn verify_fn_set_obj_well_definedness(
        &mut self,
        value: &FnSet,
        verify_state: VerifyState,
    ) -> RuntimeResult<VerifyObjWellDefinedResult> {
        let (inner, local_env) = self.run_in_local_env_and_take_env(|rt| {
            rt.verify_fn_set_obj_well_definedness_in_local(value, verify_state.clone())
        })?;
        match inner {
            Ok((param_type_well_defined, dom_fact_well_defined, ret_set_well_defined)) => {
                let proof = FnSetObjWellDefinedProof {
                    param_type_well_defined,
                    dom_fact_well_defined,
                    ret_set_well_defined,
                    local_env,
                };
                self.finish_binder_obj_success(Obj::FunctionSpace(FunctionSpace::FnSet(value.clone())), verify_state, |p| {
                    ObjWellDefinedProofByDef::FunctionSpace(FunctionSpaceObjWellDefinedProofByDef::FnSet(p))
                }, proof)
            }
            Err(reason) => Ok(VerifyObjWellDefinedResult::Failed {
                obj: Obj::FunctionSpace(FunctionSpace::FnSet(value.clone())),
                reason: FailToVerifyObjWellDefinedResult::FunctionSpace(FailToVerifyFunctionSpaceObjWellDefinedResult::FnSet(reason)),
            }),
        }
    }

    // `fn(x R) R {x + 0}` — same binder scope as FnSet, then body WD + body ∈ ret_set.
    pub(super) fn verify_anonymous_fn_obj_well_definedness(
        &mut self,
        value: &AnonymousFn,
        verify_state: VerifyState,
    ) -> RuntimeResult<VerifyObjWellDefinedResult> {
        let (inner, local_env) = self.run_in_local_env_and_take_env(|rt| {
            rt.verify_anonymous_fn_obj_well_definedness_in_local(value, verify_state.clone())
        })?;
        match inner {
            Ok((
                param_type_well_defined,
                dom_fact_well_defined,
                ret_set_well_defined,
                body_well_defined,
                body_in_ret_set,
            )) => {
                let proof = AnonymousFnObjWellDefinedProof {
                    param_type_well_defined,
                    dom_fact_well_defined,
                    ret_set_well_defined,
                    body_well_defined,
                    body_in_ret_set,
                    local_env,
                };
                self.finish_binder_obj_success(Obj::FunctionSpace(FunctionSpace::AnonymousFn(value.clone())), verify_state, |p| {
                    ObjWellDefinedProofByDef::FunctionSpace(FunctionSpaceObjWellDefinedProofByDef::AnonymousFn(p))
                }, proof)
            }
            Err(reason) => Ok(VerifyObjWellDefinedResult::Failed {
                obj: Obj::FunctionSpace(FunctionSpace::AnonymousFn(value.clone())),
                reason: FailToVerifyObjWellDefinedResult::FunctionSpace(FailToVerifyFunctionSpaceObjWellDefinedResult::AnonymousFn(reason)),
            }),
        }
    }

    // `{x R: x > 0}` — param_set WD → binder x → each fact WD; keep local_env.
    pub(super) fn verify_set_builder_obj_well_definedness(
        &mut self,
        value: &SetBuilder,
        verify_state: VerifyState,
    ) -> RuntimeResult<VerifyObjWellDefinedResult> {
        let (inner, local_env) = self.run_in_local_env_and_take_env(|rt| {
            rt.verify_set_builder_obj_well_definedness_in_local(value, verify_state.clone())
        })?;
        match inner {
            Ok((param_set_well_defined, fact_well_defined)) => {
                let proof = SetBuilderObjWellDefinedProof {
                    param_set_well_defined,
                    fact_well_defined,
                    local_env,
                };
                self.finish_binder_obj_success(Obj::SetFormer(SetFormer::SetBuilder(value.clone())), verify_state, |p| {
                    ObjWellDefinedProofByDef::SetFormer(SetFormerObjWellDefinedProofByDef::SetBuilder(p))
                }, proof)
            }
            Err(reason) => Ok(VerifyObjWellDefinedResult::Failed {
                obj: Obj::SetFormer(SetFormer::SetBuilder(value.clone())),
                reason: FailToVerifyObjWellDefinedResult::SetFormer(FailToVerifySetFormerObjWellDefinedResult::SetBuilder(reason)),
            }),
        }
    }

    fn finish_binder_obj_success<P>(
        &mut self,
        obj: Obj,
        verify_state: VerifyState,
        wrap: impl FnOnce(P) -> ObjWellDefinedProofByDef,
        proof: P,
    ) -> RuntimeResult<VerifyObjWellDefinedResult> {
        if verify_state.store_well_defined_fact {
            let wd_id = self.global_ids.allocate_well_definedness_id();
            self.top_exec_env_mut()
                .well_defined_objects
                .record(obj.clone(), wd_id);
        }
        Ok(VerifyObjWellDefinedResult::Success(ObjWellDefinedProof::ByDef {
            obj,
            proof: wrap(proof),
        }))
    }

    fn verify_fn_set_obj_well_definedness_in_local(
        &mut self,
        value: &FnSet,
        verify_state: VerifyState,
    ) -> RuntimeResult<
        Result<
            (
                Vec<Box<ObjWellDefinedProof>>,
                Vec<FactWellDefinedProof>,
                Box<ObjWellDefinedProof>,
            ),
            FailToVerifyFnSetObjWellDefined,
        >,
    > {
        if let Some(failed_index) =
            super::helper::set_bound_param_type_cites_earlier_binder(&value.set_bound_parameters)
        {
            return Ok(Err(
                FailToVerifyFnSetObjWellDefined::ParamTypeCitesEarlierBinder { failed_index },
            ));
        }

        let param_type_well_defined =
            match self.verify_set_bound_param_types_well_defined(
                &value.set_bound_parameters,
                verify_state.clone(),
            )? {
                Ok(proofs) => proofs,
                Err((failed_index, succeeded, failed_obj, failed)) => {
                    return Ok(Err(FailToVerifyFnSetObjWellDefined::ParamType {
                        failed_index,
                        succeeded,
                        failed_obj,
                        failed: Box::new(failed),
                    }));
                }
            };

        let typed = set_bound_parameters_to_typed_parameter_list(&value.set_bound_parameters);
        self.define_typed_parameters_in_current_env(&typed, None)?;

        let dom_fact_well_defined = match self.verify_quantifier_free_facts_well_defined(
            &value.dom_facts,
            verify_state.clone(),
        )? {
            Ok(proofs) => proofs,
            Err((failed_index, succeeded_dom, failed_dom)) => {
                return Ok(Err(FailToVerifyFnSetObjWellDefined::DomFact {
                    failed_index,
                    param_type_well_defined,
                    succeeded_dom,
                    failed_dom: Box::new(failed_dom),
                }));
            }
        };

        match self.verify_obj_well_definedness(value.ret_set.as_ref(), verify_state)? {
            VerifyObjWellDefinedResult::Success(ret_set_well_defined) => Ok(Ok((
                param_type_well_defined,
                dom_fact_well_defined,
                Box::new(ret_set_well_defined),
            ))),
            VerifyObjWellDefinedResult::Failed { obj: failed_obj, reason: failed } => {
                Ok(Err(FailToVerifyFnSetObjWellDefined::RetSet {
                    param_type_well_defined,
                    dom_fact_well_defined,
                    failed_obj,
                    failed: Box::new(failed),
                }))
            }
        }
    }

    fn verify_anonymous_fn_obj_well_definedness_in_local(
        &mut self,
        value: &AnonymousFn,
        verify_state: VerifyState,
    ) -> RuntimeResult<
        Result<
            (
                Vec<Box<ObjWellDefinedProof>>,
                Vec<FactWellDefinedProof>,
                Box<ObjWellDefinedProof>,
                Box<ObjWellDefinedProof>,
                VerifyFactResult,
            ),
            FailToVerifyAnonymousFnObjWellDefined,
        >,
    > {
        if let Some(failed_index) = super::helper::set_bound_param_type_cites_earlier_binder(
            &value.body.set_bound_parameters,
        ) {
            return Ok(Err(
                FailToVerifyAnonymousFnObjWellDefined::ParamTypeCitesEarlierBinder {
                    failed_index,
                },
            ));
        }

        let param_type_well_defined =
            match self.verify_set_bound_param_types_well_defined(
                &value.body.set_bound_parameters,
                verify_state.clone(),
            )? {
                Ok(proofs) => proofs,
                Err((failed_index, succeeded, failed_obj, failed)) => {
                    return Ok(Err(FailToVerifyAnonymousFnObjWellDefined::ParamType {
                        failed_index,
                        succeeded,
                        failed_obj,
                        failed: Box::new(failed),
                    }));
                }
            };

        let typed = set_bound_parameters_to_typed_parameter_list(&value.body.set_bound_parameters);
        self.define_typed_parameters_in_current_env(&typed, None)?;

        let dom_fact_well_defined = match self.verify_quantifier_free_facts_well_defined(
            &value.body.dom_facts,
            verify_state.clone(),
        )? {
            Ok(proofs) => proofs,
            Err((failed_index, succeeded_dom, failed_dom)) => {
                return Ok(Err(FailToVerifyAnonymousFnObjWellDefined::DomFact {
                    failed_index,
                    param_type_well_defined,
                    succeeded_dom,
                    failed_dom: Box::new(failed_dom),
                }));
            }
        };

        let ret_set_well_defined =
            match self.verify_obj_well_definedness(value.body.ret_set.as_ref(), verify_state.clone())?
            {
                VerifyObjWellDefinedResult::Success(proof) => Box::new(proof),
                VerifyObjWellDefinedResult::Failed { obj: failed_obj, reason: failed } => {
                    return Ok(Err(FailToVerifyAnonymousFnObjWellDefined::RetSet {
                        param_type_well_defined,
                        dom_fact_well_defined,
                        failed_obj,
                        failed: Box::new(failed),
                    }));
                }
            };

        let body_well_defined =
            match self.verify_obj_well_definedness(value.equal_to.as_ref(), verify_state.clone())? {
                VerifyObjWellDefinedResult::Success(proof) => Box::new(proof),
                VerifyObjWellDefinedResult::Failed { obj: failed_obj, reason: failed } => {
                    return Ok(Err(FailToVerifyAnonymousFnObjWellDefined::Body {
                        param_type_well_defined,
                        dom_fact_well_defined,
                        ret_set_well_defined,
                        failed_obj,
                        failed: Box::new(failed),
                    }));
                }
            };

        let membership_fact = AtomicFact::InFact(InFact {
            fact_id: self.global_ids.allocate_fact_id(),
            element: value.equal_to.as_ref().clone(),
            set: value.body.ret_set.as_ref().clone(),
            line_file: None,
        });
        let body_in_ret_set = self.verify_required_atomic_fact(
            membership_fact,
            verify_state,
            "anonymous function body must belong to the return set".to_string(),
        )?;
        if body_in_ret_set.is_failed() {
            return Ok(Err(FailToVerifyAnonymousFnObjWellDefined::BodyInRetSet {
                param_type_well_defined,
                dom_fact_well_defined,
                ret_set_well_defined,
                body_well_defined,
                failed: body_in_ret_set,
            }));
        }

        Ok(Ok((
            param_type_well_defined,
            dom_fact_well_defined,
            ret_set_well_defined,
            body_well_defined,
            body_in_ret_set,
        )))
    }

    fn verify_set_builder_obj_well_definedness_in_local(
        &mut self,
        value: &SetBuilder,
        verify_state: VerifyState,
    ) -> RuntimeResult<
        Result<
            (Box<ObjWellDefinedProof>, Vec<FactWellDefinedProof>),
            FailToVerifySetBuilderObjWellDefined,
        >,
    > {
        let param_set_well_defined =
            match self.verify_obj_well_definedness(value.param_set.as_ref(), verify_state.clone())? {
                VerifyObjWellDefinedResult::Success(proof) => Box::new(proof),
                VerifyObjWellDefinedResult::Failed { obj, reason: failed } => {
                    return Ok(Err(FailToVerifySetBuilderObjWellDefined::ParamSet {
                        obj,
                        failed: Box::new(failed),
                    }));
                }
            };

        let typed = TypedParameterList {
            groups: vec![TypedParameterGroup {
                params: vec![value.param_binding.clone()],
                param_type: ParamType::Obj(value.param_set.as_ref().clone()),
            }],
        };
        self.define_typed_parameters_in_current_env(&typed, None)?;

        let fact_well_defined =
            match self.verify_quantifier_free_facts_well_defined(&value.facts, verify_state)? {
                Ok(proofs) => proofs,
                Err((failed_index, succeeded, failed_fact)) => {
                    return Ok(Err(FailToVerifySetBuilderObjWellDefined::Fact {
                        failed_index,
                        param_set_well_defined,
                        succeeded,
                        failed: Box::new(failed_fact),
                    }));
                }
            };

        Ok(Ok((param_set_well_defined, fact_well_defined)))
    }

    fn verify_set_bound_param_types_well_defined(
        &mut self,
        list: &crate::ast::param::SetBoundParameterList,
        verify_state: VerifyState,
    ) -> RuntimeResult<
        Result<
            Vec<Box<ObjWellDefinedProof>>,
            (
                usize,
                Vec<Box<ObjWellDefinedProof>>,
                Obj,
                FailToVerifyObjWellDefinedResult,
            ),
        >,
    > {
        let mut succeeded = Vec::new();
        let mut index = 0usize;
        for group in &list.groups {
            let param_type = group.param_type.as_ref();
            match self.verify_obj_well_definedness(param_type, verify_state.clone())? {
                VerifyObjWellDefinedResult::Success(proof) => {
                    succeeded.push(Box::new(proof));
                }
                VerifyObjWellDefinedResult::Failed { obj: failed_obj, reason: failed } => {
                    return Ok(Err((index, succeeded, failed_obj, failed)));
                }
            }
            index += 1;
        }
        Ok(Ok(succeeded))
    }

    fn verify_quantifier_free_facts_well_defined(
        &mut self,
        facts: &[QuantifierFreeFact],
        verify_state: VerifyState,
    ) -> RuntimeResult<
        Result<
            Vec<FactWellDefinedProof>,
            (usize, Vec<FactWellDefinedProof>, FailToVerifyFactWellDefinedResult),
        >,
    > {
        let mut succeeded = Vec::with_capacity(facts.len());
        for (failed_index, fact) in facts.iter().enumerate() {
            let as_fact = quantifier_free_fact_to_fact(fact.clone());
            match self.verify_fact_well_definedness(&as_fact, verify_state.clone())? {
                VerifyFactWellDefinedResult::Success(proof) => {
                    // Assume earlier facts in binder scopes (FnSet/AnonymousFn dom,
                    // SetBuilder facts) before later WD checks.
                    let _ = self.store_fact_and_infer(&as_fact)?;
                    succeeded.push(proof);
                }
                VerifyFactWellDefinedResult::Failed(failed) => {
                    return Ok(Err((failed_index, succeeded, failed)));
                }
            }
        }
        Ok(Ok(succeeded))
    }
}

//! Struct / template / field-access object WD.

use super::entry::{ObjWellDefinedProof, VerifyObjWellDefinedResult};
use super::fail_to_verify_obj_well_defined::*;
use super::obj_well_defined_by_def_common::ObjWellDefinedByDefCommonStages;
use super::wrap_obj_well_defined_by_def::{finish_by_def, wrap_common_fail};
use crate::ast::fact::{
    AtomicFact, EqualFact, Fact, InFact, IsFiniteSetFact, IsNonemptySetFact, IsSetFact,
};
use crate::ast::obj::{
    FieldAccess, FunctionSpace, InstantiatedTemplateObj, Obj, StructAndFieldAccessObj, StructObj,
};
use crate::ast::param::ParamType;
use crate::ast::stmt::TemplateDefEnum;
use crate::exec_env::SpecialProperty;
use crate::execute::execute_fact_stmt::VerifyState;
use crate::runtime::runtime_ids::IdentifierId;
use crate::runtime::{Runtime, RuntimeResult};
use std::collections::HashMap;

impl Runtime {
    // `&Name` / `&Name<args>`: definition, arity, argument WD and declared types.
    // Does not prove membership `$in &Struct`.
    // Example: after `struct Point: x R; y R`, WD of `&Point` succeeds.
    pub(super) fn verify_struct_obj_well_definedness(
        &mut self,
        value: &StructObj,
        verify_state: VerifyState,
    ) -> RuntimeResult<VerifyObjWellDefinedResult> {
        let plain = value.name.local_name();
        let (expected_arity, header) = {
            let Some(def) = self.def_struct_visible(&value.name) else {
                let root =
                    Obj::StructAndFieldAccessObj(StructAndFieldAccessObj::StructObj(value.clone()));
                return Ok(VerifyObjWellDefinedResult::Failed {
                    obj: root,
                    reason: FailToVerifyObjWellDefinedResult::Structish(
                        FailToVerifyStructishObjWellDefinedResult::StructObj(
                            FailToVerifyStructObjObjWellDefined(
                                FailToVerifyObjWellDefinedByDefCommon::Others(format!(
                                    "struct `{plain}` is not defined"
                                )),
                            ),
                        ),
                    ),
                });
            };
            match &def.param_def_with_dom {
                None => (0, None),
                Some((params, dom)) => (params.ordered_param_ids().len(), Some((params.clone(), dom.clone()))),
            }
        };
        if value.params.len() != expected_arity {
            let root =
                Obj::StructAndFieldAccessObj(StructAndFieldAccessObj::StructObj(value.clone()));
            return Ok(VerifyObjWellDefinedResult::Failed {
                obj: root,
                reason: FailToVerifyObjWellDefinedResult::Structish(
                    FailToVerifyStructishObjWellDefinedResult::StructObj(
                        FailToVerifyStructObjObjWellDefined(
                            FailToVerifyObjWellDefinedByDefCommon::Others(format!(
                                "struct `{plain}` expects {expected_arity} parameter(s), got {}",
                                value.params.len()
                            )),
                        ),
                    ),
                ),
            });
        }

        let refs: Vec<&Obj> = value.params.iter().collect();
        let mut stages = self.verify_objs_as_children(&refs, verify_state.clone())?;
        let root = Obj::StructAndFieldAccessObj(StructAndFieldAccessObj::StructObj(value.clone()));
        if stages.is_fully_known() {
            if let Some((params, dom)) = header {
                let mut requirements = match self.type_facts_for_typed_arguments(&params, &value.params) {
                    Ok(facts) => facts,
                    Err(reason) => return Ok(VerifyObjWellDefinedResult::Failed {
                        obj: root.clone(),
                        reason: wrap_common_fail(&root, FailToVerifyObjWellDefinedByDefCommon::Others(reason)),
                    }),
                };
                let subst: HashMap<IdentifierId, Obj> = params.ordered_param_ids().into_iter()
                    .zip(value.params.iter().cloned()).collect();
                for fact in &dom {
                    let instantiated = match self.inst_quantifier_free_fact(fact, &subst) {
                        Ok(fact) => fact,
                        Err(error) => return Ok(VerifyObjWellDefinedResult::Failed {
                            obj: root.clone(),
                            reason: wrap_common_fail(&root, FailToVerifyObjWellDefinedByDefCommon::Others(error.to_string())),
                        }),
                    };
                    requirements.push(crate::instantiate::quantifier_free_fact_to_fact(instantiated));
                }
                for fact in &requirements {
                    let proof = self.verify_fact(fact, verify_state.clone())?;
                    let failed = proof.is_failed();
                    stages.requirement_fact_verified.push(proof);
                    if failed {
                        break;
                    }
                }
            }
        }
        match finish_by_def(&root, stages) {
            Ok(by_def) => {
                if verify_state.store_well_defined_fact {
                    let wd_id = self.global_ids.allocate_well_definedness_id();
                    self.top_exec_env_mut()
                        .well_defined_objects
                        .record(root.clone(), wd_id);
                }
                Ok(VerifyObjWellDefinedResult::Success(
                    ObjWellDefinedProof::ByDef {
                        obj: root,
                        proof: by_def,
                    },
                ))
            }
            Err(fail) => Ok(VerifyObjWellDefinedResult::Failed {
                obj: root,
                reason: fail,
            }),
        }
    }

    // `x.y` / `x.y.z`: receiver WD, then walk `fields` on the definition-time carrier.
    // Intermediate fields (all but the last) must themselves have `&Struct` type.
    // Example: after `forall p &Point:`, WD of `p.x` succeeds.
    pub(super) fn verify_field_access_obj_well_definedness(
        &mut self,
        value: &FieldAccess,
        verify_state: VerifyState,
    ) -> RuntimeResult<VerifyObjWellDefinedResult> {
        let root =
            Obj::StructAndFieldAccessObj(StructAndFieldAccessObj::FieldAccess(value.clone()));
        if value.fields.is_empty() {
            return Ok(field_access_fail(
                root,
                "field access expects at least one field name".to_string(),
            ));
        }

        let receiver_wd =
            self.verify_obj_well_definedness(value.obj.as_ref(), verify_state.clone())?;
        if receiver_wd.is_failed() {
            return Ok(VerifyObjWellDefinedResult::Failed {
                obj: root,
                reason: FailToVerifyObjWellDefinedResult::Structish(
                    FailToVerifyStructishObjWellDefinedResult::FieldAccess(
                        FailToVerifyFieldAccessObjWellDefined(
                            FailToVerifyObjWellDefinedByDefCommon::Child {
                                obj: value.obj.as_ref().clone(),
                                child: Box::new(match receiver_wd {
                                    VerifyObjWellDefinedResult::Failed { reason, .. } => reason,
                                    VerifyObjWellDefinedResult::Success(_) => unreachable!(),
                                }),
                            },
                        ),
                    ),
                ),
            });
        }

        let Some(mut carrier) = self.resolve_definition_struct_carrier(value.obj.as_ref()) else {
            return Ok(field_access_fail(
                root,
                format!(
                    "object has no definition-time struct carrier for field `{}`",
                    value.fields.join(".")
                ),
            ));
        };

        for (index, field_name) in value.fields.iter().enumerate() {
            let plain = carrier.name.local_name().to_string();
            let Some(def) = self.def_struct_visible(&carrier.name) else {
                return Ok(field_access_fail(
                    root,
                    format!("struct `{plain}` is not defined"),
                ));
            };
            let Some(field_def) = def.fields.iter().find(|f| f.binding.name == *field_name) else {
                return Ok(field_access_fail(
                    root,
                    format!("struct `{plain}` has no field `{field_name}`"),
                ));
            };
            let is_last = index + 1 == value.fields.len();
            if is_last {
                break;
            }
            match &field_def.field_type {
                Obj::StructAndFieldAccessObj(StructAndFieldAccessObj::StructObj(next)) => {
                    carrier = next.clone()
                }
                _ => {
                    return Ok(field_access_fail(
                        root,
                        format!("field `{field_name}` of struct `{plain}` is not a struct carrier"),
                    ));
                }
            }
        }

        let stages = ObjWellDefinedByDefCommonStages::from_children(vec![receiver_wd]);
        match finish_by_def(&root, stages) {
            Ok(by_def) => {
                if verify_state.store_well_defined_fact {
                    let wd_id = self.global_ids.allocate_well_definedness_id();
                    self.top_exec_env_mut()
                        .well_defined_objects
                        .record(root.clone(), wd_id);
                }
                Ok(VerifyObjWellDefinedResult::Success(
                    ObjWellDefinedProof::ByDef {
                        obj: root,
                        proof: by_def,
                    },
                ))
            }
            Err(fail) => Ok(VerifyObjWellDefinedResult::Failed {
                obj: root,
                reason: fail,
            }),
        }
    }

    // Definition-selected `DefaultStructView` only (exact ObjIR; not equality class).
    // Nested field access: walk all fields; result carrier is the last field's
    // type when that type is `&Struct`.
    pub(in crate::execute) fn resolve_definition_struct_carrier(
        &self,
        obj: &Obj,
    ) -> Option<StructObj> {
        if let Some(carrier) = self.defined_as_struct_visible_in_stack(obj) {
            return Some(carrier);
        }
        let Obj::StructAndFieldAccessObj(StructAndFieldAccessObj::FieldAccess(access)) = obj else {
            return None;
        };
        if access.fields.is_empty() {
            return None;
        }
        let mut carrier = self.resolve_definition_struct_carrier(access.obj.as_ref())?;
        for (index, field_name) in access.fields.iter().enumerate() {
            let def = self.def_struct_visible(&carrier.name)?;
            let field = def.fields.iter().find(|f| f.binding.name == *field_name)?;
            let is_last = index + 1 == access.fields.len();
            match &field.field_type {
                Obj::StructAndFieldAccessObj(StructAndFieldAccessObj::StructObj(next)) => {
                    if is_last {
                        return Some(next.clone());
                    }
                    carrier = next.clone();
                }
                _ => {
                    if is_last {
                        return None;
                    }
                    return None;
                }
            }
        }
        None
    }

    pub(super) fn defined_as_struct_visible_in_stack(&self, obj: &Obj) -> Option<StructObj> {
        let key = obj.ir();
        for env in self.execution_environments_stack.iter().rev() {
            let Some(props) = env.special_properties.get(&key) else {
                continue;
            };
            for prop in props {
                if let SpecialProperty::DefaultStructView(fact) = prop {
                    if let Obj::StructAndFieldAccessObj(StructAndFieldAccessObj::StructObj(carrier)) = &fact.set {
                        return Some(carrier.clone());
                    }
                }
            }
        }
        None
    }

    // `\Name<args>`: known template, matching arity, args WD, param-type + domain obligations.
    // Surface stays InstantiatedTemplateObj (no materialization).
    // Example: after `template<S set>: have carrier_copy set = S`, WD of `\carrier_copy<R>`.
    pub(super) fn verify_instantiated_template_obj_well_definedness(
        &mut self,
        value: &InstantiatedTemplateObj,
        verify_state: VerifyState,
    ) -> RuntimeResult<VerifyObjWellDefinedResult> {
        let plain = value.template_name.local_name();
        let (expected_arity, param_groups, dom_facts) = {
            let Some(def) = self.def_template_visible(&value.template_name) else {
                return Ok(template_fail(
                    Obj::InstantiatedTemplateObj(value.clone()),
                    FailToVerifyObjWellDefinedByDefCommon::Others(format!(
                        "template `{plain}` is not defined"
                    )),
                ));
            };
            (
                def.template_arg_def.ordered_param_ids().len(),
                def.template_arg_def.groups.clone(),
                def.template_arg_dom.clone(),
            )
        };
        if value.args.len() != expected_arity {
            return Ok(template_fail(
                Obj::InstantiatedTemplateObj(value.clone()),
                FailToVerifyObjWellDefinedByDefCommon::Others(format!(
                    "template `{plain}` expects {expected_arity} argument(s), got {}",
                    value.args.len()
                )),
            ));
        }

        let mut stages = ObjWellDefinedByDefCommonStages::leaf();
        for arg in &value.args {
            let child = self.verify_obj_well_definedness(arg, verify_state.clone())?;
            let failed = child.is_failed();
            stages.child_obj_well_defined.push(child);
            if failed {
                let root = Obj::InstantiatedTemplateObj(value.clone());
                return Ok(match finish_by_def(&root, stages) {
                    Ok(_) => unreachable!(),
                    Err(fail) => VerifyObjWellDefinedResult::Failed {
                        obj: root,
                        reason: fail,
                    },
                });
            }
        }

        let param_ids = {
            let mut ids = Vec::with_capacity(expected_arity);
            for group in &param_groups {
                for param in &group.params {
                    ids.push(param.id);
                }
            }
            ids
        };
        let mut subst: HashMap<IdentifierId, Obj> = HashMap::new();
        for (id, arg) in param_ids.iter().zip(value.args.iter()) {
            subst.insert(*id, arg.clone());
        }

        let mut arg_index = 0;
        for group in &param_groups {
            let param_type = match self.inst_param_type(&group.param_type, &subst) {
                Ok(param_type) => param_type,
                Err(_) => {
                    return Ok(template_fail(
                        Obj::InstantiatedTemplateObj(value.clone()),
                        FailToVerifyObjWellDefinedByDefCommon::Others(format!(
                            "template `{plain}`: failed to instantiate parameter type"
                        )),
                    ));
                }
            };
            for _param in &group.params {
                let arg = &value.args[arg_index];
                let type_fact = type_fact_for_instantiated_template_arg(
                    arg.clone(),
                    &param_type,
                    self.global_ids.allocate_fact_id(),
                );
                let req = self.verify_fact(&type_fact, verify_state.clone())?;
                let failed = req.is_failed();
                stages.requirement_fact_verified.push(req);
                if failed {
                    let root = Obj::InstantiatedTemplateObj(value.clone());
                    return Ok(match finish_by_def(&root, stages) {
                        Ok(_) => unreachable!(),
                        Err(fail) => VerifyObjWellDefinedResult::Failed {
                            obj: root,
                            reason: fail,
                        },
                    });
                }
                arg_index += 1;
            }
        }

        for dom in &dom_facts {
            let instantiated = match self.inst_quantifier_free_fact(dom, &subst) {
                Ok(f) => f,
                Err(_) => {
                    return Ok(template_fail(
                        Obj::InstantiatedTemplateObj(value.clone()),
                        FailToVerifyObjWellDefinedByDefCommon::Others(format!(
                            "template `{plain}`: failed to instantiate domain fact"
                        )),
                    ));
                }
            };
            let req =
                self.verify_required_quantifier_free_fact(instantiated, verify_state.clone())?;
            let failed = req.is_failed();
            stages.requirement_fact_verified.push(req);
            if failed {
                let root = Obj::InstantiatedTemplateObj(value.clone());
                return Ok(match finish_by_def(&root, stages) {
                    Ok(_) => unreachable!(),
                    Err(fail) => VerifyObjWellDefinedResult::Failed {
                        obj: root,
                        reason: fail,
                    },
                });
            }
        }

        let root = Obj::InstantiatedTemplateObj(value.clone());
        match finish_by_def(&root, stages) {
            Ok(by_def) => {
                if verify_state.store_well_defined_fact {
                    let wd_id = self.global_ids.allocate_well_definedness_id();
                    self.top_exec_env_mut()
                        .well_defined_objects
                        .record(root.clone(), wd_id);
                    // Have-fn template bodies: register the surface as callable so
                    // `\T<a>(x)` reuses ordinary InFunctionSet application WD.
                    // Have-obj bodies: store `\T<a> = subst(rhs)` for definitional use.
                    self.maybe_register_instantiated_template_definitional_facts(value)?;
                }
                Ok(VerifyObjWellDefinedResult::Success(
                    ObjWellDefinedProof::ByDef {
                        obj: root,
                        proof: by_def,
                    },
                ))
            }
            Err(fail) => Ok(VerifyObjWellDefinedResult::Failed {
                obj: root,
                reason: fail,
            }),
        }
    }

    // After WD of `\Name<args>`, store definitional facts for supported bodies:
    // - have fn =: `\Name<args> $in inst(FnSet)` and `\Name<args> = inst(anon)`
    // - have fn by cases / by induc: `\Name<args> $in inst(FnSet)` (no anon equality)
    // - have =: `\Name<args> = subst(rhs)`
    // - have by replacement_axiom: `$is_set(\Name<args>)` plus intro/elim foralls
    fn maybe_register_instantiated_template_definitional_facts(
        &mut self,
        value: &InstantiatedTemplateObj,
    ) -> RuntimeResult<()> {
        let Some(def) = self.def_template_visible(&value.template_name).cloned() else {
            return Ok(());
        };
        let mut subst: HashMap<IdentifierId, Obj> = HashMap::new();
        for (id, arg) in def
            .template_arg_def
            .ordered_param_ids()
            .into_iter()
            .zip(value.args.iter())
        {
            subst.insert(id, arg.clone());
        }
        match &def.template_def_stmt {
            TemplateDefEnum::HaveFnEqualStmt(have_fn) => {
                let Ok(anon) = self.inst_obj(
                    &Obj::FunctionSpace(FunctionSpace::AnonymousFn(
                        have_fn.equal_to_anonymous_fn.clone(),
                    )),
                    &subst,
                ) else {
                    return Ok(());
                };
                let Obj::FunctionSpace(FunctionSpace::AnonymousFn(anon)) = anon else {
                    return Ok(());
                };
                let surface = Obj::InstantiatedTemplateObj(value.clone());
                let membership = Fact::AtomicFact(AtomicFact::InFact(InFact {
                    fact_id: self.global_ids.allocate_fact_id(),
                    element: surface.clone(),
                    set: Obj::FunctionSpace(FunctionSpace::FnSet(anon.body.clone())),
                    line_file: None,
                }));
                self.store_fact_and_infer(&membership)?;
                let defining_equal = Fact::AtomicFact(AtomicFact::EqualFact(EqualFact {
                    fact_id: self.global_ids.allocate_fact_id(),
                    left: surface,
                    right: Obj::FunctionSpace(FunctionSpace::AnonymousFn(anon)),
                    line_file: None,
                }));
                self.store_fact_and_infer(&defining_equal)?;
            }
            TemplateDefEnum::HaveFnEqualCaseByCaseStmt(have_fn) => {
                self.store_instantiated_template_fn_set_membership(
                    value,
                    &have_fn.fn_set_clause,
                    &subst,
                )?;
            }
            TemplateDefEnum::HaveFnByInducStmt(have_fn) => {
                self.store_instantiated_template_fn_set_membership(
                    value,
                    &have_fn.fn_set_clause,
                    &subst,
                )?;
            }
            TemplateDefEnum::HaveFnByForallExistUniqueStmt(stmt) => {
                // Same three facts as plain `have fn by exist!` / `release obj def`,
                // with subjects = `\Name<args>` and template params substituted.
                let surface = Obj::InstantiatedTemplateObj(value.clone());
                match self.build_have_fn_by_forall_exist_unique_facts_for_surface(&surface, stmt)? {
                    Ok((membership, property, uniqueness)) => {
                        for fact in [membership, property, uniqueness] {
                            let Ok(inst) = self.inst_fact(&fact, &subst) else {
                                return Ok(());
                            };
                            self.store_fact_and_infer(&inst)?;
                        }
                    }
                    Err(_) => {}
                }
            }
            TemplateDefEnum::HaveObjEqualStmt(_) => {
                let Some(expanded_rhs) =
                    self.expanded_have_obj_equal_rhs_of_instantiated_template(value)?
                else {
                    return Ok(());
                };
                let surface = Obj::InstantiatedTemplateObj(value.clone());
                let defining_equal = Fact::AtomicFact(AtomicFact::EqualFact(EqualFact {
                    fact_id: self.global_ids.allocate_fact_id(),
                    left: surface,
                    right: expanded_rhs,
                    line_file: None,
                }));
                self.store_fact_and_infer(&defining_equal)?;
            }
            TemplateDefEnum::HaveByReplacementAxiomStmt(stmt) => {
                // Same three facts as plain `have … by replacement_axiom` / release:
                // `$is_set`, intro forall, elim forall — with `\Name<args>` as Img
                // and template params substituted into the source set.
                let Ok(source_set) = self.inst_obj(&stmt.source_set, &subst) else {
                    return Ok(());
                };
                let mut stmt_inst = stmt.clone();
                stmt_inst.source_set = source_set;
                let img = Obj::InstantiatedTemplateObj(value.clone());
                let type_fact = Fact::AtomicFact(AtomicFact::IsSetFact(IsSetFact {
                    fact_id: self.global_ids.allocate_fact_id(),
                    set: img.clone(),
                    line_file: None,
                }));
                let intro = Fact::ForallFact(self.replacement_intro_forall(&stmt_inst, &img));
                let elim = Fact::ForallFact(self.replacement_elim_forall(&stmt_inst, &img));
                for fact in [type_fact, intro, elim] {
                    self.store_fact_and_infer(&fact)?;
                }
            }
            _ => {}
        }
        Ok(())
    }

    fn store_instantiated_template_fn_set_membership(
        &mut self,
        value: &InstantiatedTemplateObj,
        clause: &crate::ast::stmt::FnSetClause,
        subst: &HashMap<IdentifierId, Obj>,
    ) -> RuntimeResult<()> {
        let fn_set = crate::ast::obj::FnSet {
            set_bound_parameters: clause.set_bound_parameters.clone(),
            dom_facts: clause.dom_facts.clone(),
            ret_set: Box::new(clause.ret_set.clone()),
        };
        let Ok(inst_set) = self.inst_obj(&Obj::FunctionSpace(FunctionSpace::FnSet(fn_set)), subst)
        else {
            return Ok(());
        };
        let Obj::FunctionSpace(FunctionSpace::FnSet(_)) = &inst_set else {
            return Ok(());
        };
        let surface = Obj::InstantiatedTemplateObj(value.clone());
        let membership = Fact::AtomicFact(AtomicFact::InFact(InFact {
            fact_id: self.global_ids.allocate_fact_id(),
            element: surface,
            set: inst_set,
            line_file: None,
        }));
        self.store_fact_and_infer(&membership)?;
        Ok(())
    }
}

fn template_fail(
    obj: Obj,
    common: FailToVerifyObjWellDefinedByDefCommon,
) -> VerifyObjWellDefinedResult {
    VerifyObjWellDefinedResult::Failed {
        obj,
        reason: FailToVerifyObjWellDefinedResult::InstantiatedTemplateObj(
            FailToVerifyInstantiatedTemplateObjObjWellDefined(common),
        ),
    }
}

fn field_access_fail(obj: Obj, message: String) -> VerifyObjWellDefinedResult {
    VerifyObjWellDefinedResult::Failed {
        obj,
        reason: FailToVerifyObjWellDefinedResult::Structish(
            FailToVerifyStructishObjWellDefinedResult::FieldAccess(
                FailToVerifyFieldAccessObjWellDefined(
                    FailToVerifyObjWellDefinedByDefCommon::Others(message),
                ),
            ),
        ),
    }
}

// Same shapes as forall instantiation param-type obligations.
fn type_fact_for_instantiated_template_arg(
    arg: Obj,
    param_type: &ParamType,
    fact_id: crate::runtime::FactId,
) -> Fact {
    match param_type {
        ParamType::Obj(param_set) => Fact::AtomicFact(AtomicFact::InFact(InFact {
            fact_id,
            element: arg,
            set: param_set.clone(),
            line_file: None,
        })),
        ParamType::Set(_) => Fact::AtomicFact(AtomicFact::IsSetFact(IsSetFact {
            fact_id,
            set: arg,
            line_file: None,
        })),
        ParamType::NonemptySet(_) => {
            Fact::AtomicFact(AtomicFact::IsNonemptySetFact(IsNonemptySetFact {
                fact_id,
                set: arg,
                line_file: None,
            }))
        }
        ParamType::FiniteSet(_) => Fact::AtomicFact(AtomicFact::IsFiniteSetFact(IsFiniteSetFact {
            fact_id,
            set: arg,
            line_file: None,
        })),
    }
}

